union all select cl.credit_mst_id creditMstId, mci.customer_name subjectName, cl.credit_type creditType, NVL(cl.credit_amt_add,0) creditAmt, cci.term maxTimeLimit, cti.risk_ratio warningRatio, NVL(cl.credit_amt_add,0)-NVL(cl.hap_credit_amt,0) availableCredit, NVL(cl.hap_credit_amt,0) hapCreditAmt, cuca.amount adjustCredit, null tradeFace, cti.org_type orgType, null orgTier, case when (NVL(cl.hap_credit_amt,0)/NVL(cl.credit_amt_add,null)) < 0.8 then '01' when (NVL(cl.hap_credit_amt,0)/NVL(cl.credit_amt_add,null)) >= 0.8 and (NVL(cl.hap_credit_amt,0)/NVL(cl.credit_amt_add,null)) <= 1 then '02' else '03' end supStatus from credit_lines cl left join credit_using_customer_ajust cuca on cl.seqno = cuca.seqno left join mst_customer_info mci on cl.customer_id = mci.customer_id left join credit_conf_info cci on cl.credit_mst_id = cci.credit_mst_id left join credit_tag_info cti on cci.credit_tag_id = cti.credit_tag_id
